#include <bits/stdc++.h>
using namespace std;

typedef long long ll;


ll getVal(int a, int b, const vector<ll>& prefix, int n) {
    return (2LL * prefix[a]) + 
    (prefix[a + 2 * b]) + 
    (3LL * prefix[(3 * n) - (2 * a) - b]);
}

int main() {
    int t;
    cin >> t;
    while (t--) {
        int n;
        cin >> n;
        vector<ll> ratings(3 * n, 0);
        
        for (ll& rat: ratings) {
            cin >> rat;
        }
        
        // max -> min ratings sort
        sort(ratings.begin(), ratings.end());
        reverse(ratings.begin(), ratings.end());
        
        vector<ll> prefix(3 * n + 1, 0);
        
        for (int i {0}; i < 3 * n; ++i) {
            prefix[i + 1] = prefix[i] + ratings[i];
        }
        
        // a: no. of teams for which their 'strength' is determined by 
        // 6 * x term. 
        // b: 4x + 4y
        // c: n - a - b => 3x + 3y + 3z
        
        
        
        ll res {0};
        
        
        int b = 0;
        for (int a = n; a >= 0; --a) {
            b = min(b, n - a);
            
            while (b < n - a) {
                ll curr = getVal(a, b, prefix, n);
                ll next = getVal(a, b + 1, prefix, n);
                
                if (next >= curr) ++b;
                else break;
            }
            
            res = max(res, getVal(a, b, prefix, n));
        }
        
        cout << res << "\n";
    }
    
    return 0;
}
